import React from 'react';
import {RouteComponentProps, withRouter} from "react-router-dom";
import cx from 'classnames';
import _T from '../lang';
import Footer from "../footer";
import LinearProgress from '@material/react-linear-progress';

import bs from "../styles/styles.module.scss";
import "../styles/styles.scss";
import formStyle from './form.module.scss';
import './mdc.scss';
import {MatchProps} from "../interfaces";

const RequestForm = React.lazy(() => import('./request-form'));

const GetConnected = (props: RouteComponentProps<MatchProps>) => {
    const [isLoading, setIsLoading] = React.useState(false);
    let lang = props.match.params.lang;

    function handleSubmit() {
        setIsLoading(true);
    }

    function handleBack() {
        props.history.goBack();
    }

    return (
        <div>
            <div className={formStyle.container}>
                <div className={cx(formStyle.containerFrame)}>
                    {isLoading && <LinearProgress indeterminate={true}/>}
                    <div className={formStyle.containerPadding} id="connect-form">
                        {lang === "en" &&
                        <div className={cx(bs["alert"], bs["alert-warning"])} role="alert">
                            Currently, the submission does NOT work, please <a href="mailto:noc@gtdev.org">send email</a> to us directly.
                        </div>
                        }
                        {lang === "zh_CN" &&
                        <div className={cx(bs["alert"], bs["alert-warning"])} role="alert">
                            目前，此表单的提交功能<b>不可用</b>，请直接给我们<a href="mailto:noc@gtdev.org">发送电子邮件</a>。
                        </div>
                        }
                        <h2 className={cx(bs["text-center"], bs["mb-1"])}>GTDev Network</h2>
                        <h4 className={cx(bs["text-center"], bs["mb-3"])}>{_T(lang, "Peering Request Form")}</h4>
                        <RequestForm handleSubmit={handleSubmit} lang={lang} handleBack={handleBack}/>
                    </div>
                </div>
            </div>
            <Footer lang={lang}/>
        </div>
    );
};

export default withRouter(GetConnected);